{
  "name": "XCalibur 分配阀注射泵",
  "name_en": "XCalibur Syringe Pump with Distribution Valve",
  "manufacturer": "Tecan Cavro",
  "description": "用于实验室液路切换与精密吸液/分液的 XCalibur 注射泵。该设备可控制柱塞绝对/相对位置、阀口切换、运行速度、微步模式和命令序列，并支持向废液口排放、管路预充和初始化，适合自动化样品转移、灌注和流体处理。",
  "description_en": "An XCalibur syringe pump for laboratory fluid routing and precise aspiration/dispensing. It controls absolute/relative plunger motion, valve port switching, motion speeds, microstepping, and command sequences, and supports waste dispensing, line priming, and initialization for automated sample transfer, priming, and fluid handling.",
  "tag_hints": [
    "syringe pump",
    "distribution valve",
    "liquid handling",
    "plunger motion control",
    "port switching",
    "sample aspiration and dispensing",
    "line priming",
    "automated fluid routing"
  ],
  "actions": [
    {
      "action_name": "auto-initDebugLogging",
      "description": "初始化调试日志记录。",
      "description_en": "Initialize debug logging."
    },
    {
      "action_name": "auto-logCall",
      "description": "记录函数调用参数。",
      "description_en": "Log function call parameters."
    },
    {
      "action_name": "auto-logDebug",
      "description": "写入调试消息。",
      "description_en": "Write a debug message."
    },
    {
      "action_name": "auto-init",
      "description": "初始化注射泵，并按需要设置方向与输入/输出端口。",
      "description_en": "Initialize the syringe pump and optionally set direction and input/output ports."
    },
    {
      "action_name": "auto-extractToWaste",
      "description": "从指定端口吸取液体；当行程超限时自动排至废液口后继续吸液。",
      "description_en": "Aspirate from a specified port; if the stroke would exceed range, dispense to waste and continue aspirating."
    },
    {
      "action_name": "auto-primePort",
      "description": "对指定端口进行管路预充。",
      "description_en": "Prime the line on a specified port."
    },
    {
      "action_name": "auto-executeChain",
      "description": "执行当前命令链并复位命令链状态。",
      "description_en": "Execute the current command chain and reset the chain state."
    },
    {
      "action_name": "auto-resetChain",
      "description": "重置命令链及其执行时间状态。",
      "description_en": "Reset the command chain and its execution-time state."
    },
    {
      "action_name": "auto-updateSimState",
      "description": "更新模拟状态缓存。",
      "description_en": "Update the cached simulation state."
    },
    {
      "action_name": "auto-cacheSimSpeeds",
      "description": "缓存模拟速度设置。",
      "description_en": "Cache simulation speed settings."
    },
    {
      "action_name": "auto-restoreSimSpeeds",
      "description": "恢复已缓存的模拟速度设置。",
      "description_en": "Restore cached simulation speed settings."
    },
    {
      "action_name": "auto-execWrap",
      "description": "定义可立即执行链式命令的包装行为。",
      "description_en": "Define wrapping behavior that allows immediate execution of chainable commands."
    },
    {
      "action_name": "auto-dispenseToWaste",
      "description": "将注射器当前内容物排至废液口。",
      "description_en": "Dispense the current syringe contents to the waste port."
    },
    {
      "action_name": "auto-extract",
      "description": "从指定端口吸取指定体积液体。",
      "description_en": "Aspirate a specified volume from a specified port."
    },
    {
      "action_name": "auto-dispense",
      "description": "向指定端口分配指定体积液体。",
      "description_en": "Dispense a specified volume to a specified port."
    },
    {
      "action_name": "auto-changePort",
      "description": "切换分配阀到指定端口。",
      "description_en": "Switch the distribution valve to a specified port."
    },
    {
      "action_name": "auto-movePlungerAbs",
      "description": "将柱塞移动到绝对位置。",
      "description_en": "Move the plunger to an absolute position."
    },
    {
      "action_name": "auto-movePlungerRel",
      "description": "将柱塞按相对位移移动。",
      "description_en": "Move the plunger by a relative displacement."
    },
    {
      "action_name": "auto-setSpeed",
      "description": "设置运行速度代码。",
      "description_en": "Set the motion speed code."
    },
    {
      "action_name": "auto-setStartSpeed",
      "description": "设置起始速度。",
      "description_en": "Set the start speed."
    },
    {
      "action_name": "auto-setTopSpeed",
      "description": "设置最高速度。",
      "description_en": "Set the top speed."
    },
    {
      "action_name": "auto-setCutoffSpeed",
      "description": "设置截止速度。",
      "description_en": "Set the cutoff speed."
    },
    {
      "action_name": "auto-setSlope",
      "description": "设置速度斜率代码。",
      "description_en": "Set the acceleration slope code."
    },
    {
      "action_name": "auto-repeatCmdSeq",
      "description": "重复执行命令序列。",
      "description_en": "Repeat a command sequence."
    },
    {
      "action_name": "auto-markRepeatStart",
      "description": "标记重复命令序列的起点。",
      "description_en": "Mark the start of a repeated command sequence."
    },
    {
      "action_name": "auto-delayExec",
      "description": "延迟命令执行指定时间。",
      "description_en": "Delay command execution for a specified time."
    },
    {
      "action_name": "auto-haltExec",
      "description": "暂停命令执行，直到收到继续命令或外部输入触发。",
      "description_en": "Halt command execution until a resume command or external input trigger is received."
    },
    {
      "action_name": "auto-updateSpeeds",
      "description": "读取并更新当前速度设置。",
      "description_en": "Read and update the current speed settings."
    },
    {
      "action_name": "auto-getPlungerPos",
      "description": "获取柱塞绝对位置。",
      "description_en": "Get the absolute plunger position."
    },
    {
      "action_name": "auto-getStartSpeed",
      "description": "获取起始速度。",
      "description_en": "Get the start speed."
    },
    {
      "action_name": "auto-getTopSpeed",
      "description": "获取最高速度。",
      "description_en": "Get the top speed."
    },
    {
      "action_name": "auto-getCutoffSpeed",
      "description": "获取截止速度。",
      "description_en": "Get the cutoff speed."
    },
    {
      "action_name": "auto-getEncoderPos",
      "description": "获取柱塞轴当前编码器位置。",
      "description_en": "Get the current encoder position of the plunger axis."
    },
    {
      "action_name": "auto-getCurPort",
      "description": "获取当前阀口位置。",
      "description_en": "Get the current valve port position."
    },
    {
      "action_name": "auto-getBufferStatus",
      "description": "获取命令缓冲区状态。",
      "description_en": "Get the command buffer status."
    },
    {
      "action_name": "auto-setMicrostep",
      "description": "设置微步模式开关。",
      "description_en": "Set microstep mode on or off."
    },
    {
      "action_name": "auto-terminateCmd",
      "description": "终止当前命令。",
      "description_en": "Terminate the current command."
    },
    {
      "action_name": "auto-waitReady",
      "description": "等待注射泵就绪以接受下一条命令。",
      "description_en": "Wait for the syringe pump to become ready for the next command."
    },
    {
      "action_name": "auto-sendRcv",
      "description": "发送原始命令字符串并接收解析后的响应。",
      "description_en": "Send a raw command string and receive the parsed response."
    }
  ]
}

